const crypto = require('crypto');
// Convex signs `${timestamp}.${rawBody}` with the shared secret (convex/lib/hmac.ts).
// Verify the raw bytes: re-serialising the parsed body could change them.
const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const signature = String(headers['x-lendloop-signature'] ?? '');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;

const expected = 'sha256=' + crypto.createHmac('sha256', secret ?? '').update(`${timestamp}.${raw}`).digest('hex');
const fresh = Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
const a = Buffer.from(signature);
const b = Buffer.from(expected);
const valid = Boolean(secret) && fresh && a.length === b.length && crypto.timingSafeEqual(a, b);

// Pass on only the parsed event, never the headers or the raw body.
return [{ json: { valid, event: valid ? JSON.parse(raw) : null } }];

// One short message per loan event. The payload holds only what this needs.
const e = $input.first().json.event;
const dates = `${e.startDate} to ${e.endDate}`;
const messages = {
  requested: [`${e.otherPartyName} wants to borrow your ${e.toolName}`,
    `${e.otherPartyName} asked to borrow your ${e.toolName} (${dates}). Open LendLoop to approve or decline.`],
  approved: [`Approved: ${e.toolName}`,
    `${e.otherPartyName} approved your request for the ${e.toolName} (${dates}).`],
  declined: [`Declined: ${e.toolName}`,
    `${e.otherPartyName} declined your request for the ${e.toolName} (${dates}).`],
  returned: [`Returned: ${e.toolName}`,
    `${e.otherPartyName} marked the ${e.toolName} as returned. Thanks for borrowing!`],
};
const [subject, body] = messages[e.event] ?? [`LendLoop update: ${e.toolName}`, `Your loan is now ${e.status}.`];
return [{
  json: {
    key: e.key,
    to: `${e.recipient.name} <${e.recipient.email}>`,
    subject,
    text: `Hi ${e.recipient.name},\n\n${body}\n\n— LendLoop`,
  },
}];
